    "ja": "\u5BB6\u5EAD\u306E\u30D5\u30E9\u30A4\u30D1\u30F3\u3067\u30D7\u30ED\u306E\u5473\uFF01\u5C71\u828B\u30D1\u30EF\u30FC\u3067\u51B7\u3081\u3066\u3082\u3075\u3063\u304F\u3089\u6975\u4E0A\u306E\u4ED5\u4E0A\u304C\u308A\u3002",
    "ko": "\uC6D0\uD558\uB294 \uC7AC\uB8CC\uB97C \uB9C8\uC74C\uAECF! \uD504\uB77C\uC774\uD32C\uC73C\uB85C \uB9CC\uB4DC\uB294 \uB450\uD23C\uD558\uACE0 \uCD09\uCD09\uD55C \uC815\uD1B5 \uB9DB.",
    "th": "\u0E43\u0E2A\u0E48\u0E40\u0E04\u0E23\u0E37\u0E48\u0E2D\u0E07\u0E44\u0E14\u0E49\u0E15\u0E32\u0E21\u0E43\u0E08\u0E0A\u0E2D\u0E1A \u0E17\u0E33\u0E07\u0E48\u0E32\u0E22\u0E14\u0E49\u0E27\u0E22\u0E01\u0E23\u0E30\u0E17\u0E30\u0E17\u0E35\u0E48\u0E1A\u0E49\u0E32\u0E19 \u0E2B\u0E19\u0E32 \u0E19\u0E38\u0E48\u0E21 \u0E2D\u0E23\u0E48\u0E2D\u0E22\u0E23\u0E30\u0E14\u0E31\u0E1A\u0E23\u0E49\u0E32\u0E19\u0E14\u0E31\u0E07"
