        "ko": "\uC544\uC624\uB178\uB9AC",
        "th": "\u0E2A\u0E32\u0E2B\u0E23\u0E48\u0E32\u0E22\u0E1C\u0E07\u0E40\u0E02\u0E35\u0E22\u0E27"
