    "ko": "\uB9C8\uCE20\uB9AC\uC758 \uAF43! \uBA74\uC744 \uBA3C\uC800 \uBC14\uC0AD\uD558\uAC8C \uAD6C\uC6B4 \uB4A4 \uBCF6\uC544\uB0B4\uB294 \uC804\uBB38\uAC00\uC758 \uBE44\uBC95.",
