      "ja": "\u662D\u548C\u521D\u671F\u306B\u4E2D\u83EF\u305D\u3070\u306B\u30A6\u30B9\u30BF\u30FC\u30BD\u30FC\u30B9\u3092\u5408\u308F\u305B\u305F\u306E\u304C\u59CB\u307E\u308A\u3002\u30BD\u30FC\u30B9\u304C\u713C\u3051\u308B\u9B45\u60D1\u7684\u306A\u5302\u3044\u306F\u3001\u65E5\u672C\u306E\u796D\u308A\u306E\u539F\u98A8\u666F\u3067\u3059\u3002",
      "ko": "\uC1FC\uC640 \uCD08\uAE30\uC5D0 \uC911\uD654\uBA74\uC5D0 \uC6B0\uC2A4\uD130\uC18C\uC2A4\uB97C \uC811\uBAA9\uD558\uC5EC \uD0C4\uC0DD\uD55C \uB300\uC911 \uC694\uB9AC\uB85C \uCD95\uC81C \uD3EC\uC7A5\uB9C8\uCC28\uC758 \uC0C1\uC9D5\uC774 \uB418\uC5C8\uC2B5\uB2C8\uB2E4.",
      "th": "\u0E40\u0E01\u0E34\u0E14\u0E02\u0E36\u0E49\u0E19\u0E43\u0E19\u0E22\u0E38\u0E04\u0E42\u0E0A\u0E27\u0E30 \u0E42\u0E14\u0E22\u0E19\u0E33\u0E40\u0E2A\u0E49\u0E19\u0E1A\u0E30\u0E2B\u0E21\u0E35\u0E48\u0E21\u0E32\u0E1C\u0E31\u0E14\u0E01\u0E31\u0E1A\u0E0B\u0E2D\u0E2A\u0E27\u0E39\u0E2A\u0E40\u0E15\u0E2D\u0E23\u0E4C\u0E2A\u0E44\u0E15\u0E25\u0E4C\u0E0D\u0E35\u0E48\u0E1B\u0E38\u0E48\u0E19 \u0E01\u0E25\u0E34\u0E48\u0E19\u0E2B\u0E2D\u0E21\u0E1F\u0E38\u0E49\u0E07\u0E44\u0E1B\u0E17\u0E31\u0E48\u0E27\u0E07\u0E32\u0E19\u0E40\u0E17\u0E28\u0E01\u0E32\u0E25"
