    "ko": "\uCE20\uD150\uCE74\uCFE0 \uD0C0\uC6CC \uC544\uB798\uC758 \uBA85\uBB3C! \uAE30\uB984\uC9C0\uC9C0 \uC54A\uACE0 \uD30C\uC0AD\uD558\uAC8C \uC990\uAE30\uB294 \uC77C\uBCF8\uC2DD \uAF2C\uCE58\uD280\uAE40.",
    "th": "\u0E2D\u0E32\u0E2B\u0E32\u0E23\u0E22\u0E2D\u0E14\u0E2E\u0E34\u0E15\u0E43\u0E15\u0E49\u0E2B\u0E2D\u0E04\u0E2D\u0E22\u0E0B\u0E36\u0E40\u0E17\u0E19\u0E04\u0E32\u0E04\u0E38 \u0E01\u0E23\u0E2D\u0E1A\u0E40\u0E1A\u0E32\u0E44\u0E21\u0E48\u0E2D\u0E21\u0E19\u0E49\u0E33\u0E21\u0E31\u0E19 \u0E17\u0E33\u0E14\u0E49\u0E27\u0E22\u0E2B\u0E21\u0E49\u0E2D\u0E17\u0E2D\u0E14\u0E44\u0E23\u0E49\u0E19\u0E49\u0E33\u0E21\u0E31\u0E19\u0E44\u0E14\u0E49"
