    historyStory: {
      "zh-TW": "\u5927\u6B63\u672B\u671F\u81F3\u662D\u548C\u521D\u671F\uFF0C\u65B0\u4E16\u754C\u805A\u96C6\u8A31\u591A\u5F9E\u4E8B\u7E41\u91CD\u9AD4\u529B\u52DE\u52D5\u7684\u78BC\u982D\u8207\u5EFA\u7BC9\u5DE5\u4EBA\u3002\u70BA\u4E86\u8B93\u5DE5\u4EBA\u5011\u82B1\u5C0F\u9322\u5C31\u80FD\u5403\u98FD\uFF0C\u5E97\u5BB6\u5C07\u725B\u8089\u3001\u9D6A\u9D89\u86CB\u3001\u6D0B\u8525\u5207\u584A\u4E32\u5728\u7AF9\u7C64\u4E0A\uFF0C\u88F9\u4E0A\u539A\u9EB5\u8863\u6CBE\u8D85\u7D30\u9EB5\u5305\u7C89\u9165\u70B8\uFF0C\u6CBE\u4E0A\u5171\u7528\u9435\u76D2\u91AC\u6C41\uFF0C\u642D\u914D\u65B0\u9BAE\u89E3\u81A9\u7684\u514D\u8CBB\u751F\u9AD8\u9E97\u83DC\uFF0C\u8A95\u751F\u4E86\u98A8\u9761\u5168\u7403\u7684\u5927\u962A\u4E32\u70B8\u6587\u5316\uFF01",
      "en": "Born in the 1920s to feed hungry working-class laborers cheaply. Beef, lotus root, and quail eggs are skewered, coated in fine panko, and dipped into communal sauce tanks.",
      "ja": "\u5927\u6B63\u304B\u3089\u662D\u548C\u521D\u671F\u3001\u65B0\u4E16\u754C\u306E\u52B4\u50CD\u8005\u306E\u305F\u3081\u306B\u5B89\u304F\u3066\u6E80\u8179\u306B\u306A\u308B\u3088\u3046\u8003\u6848\u3055\u308C\u305F\u306E\u304C\u59CB\u307E\u308A\u3002\u30B5\u30AF\u30B5\u30AF\u306E\u7D30\u304B\u3044\u8863\u3068\u30AD\u30E3\u30D9\u30C4\u304C\u7279\u5FB4\u3002",
      "ko": "1920\uB144\uB300 \uC624\uC0AC\uCE74\uC758 \uB178\uB3D9\uC790\uB4E4\uC744 \uC704\uD574 \uC800\uB834\uD558\uACE0 \uB4E0\uB4E0\uD558\uAC8C \uBA39\uC744 \uC218 \uC788\uB3C4\uB85D \uACE0\uC548\uB41C \uC11C\uBBFC \uAF2C\uCE58\uD280\uAE40\uC785\uB2C8\uB2E4.",
      "th": "\u0E40\u0E23\u0E34\u0E48\u0E21\u0E15\u0E49\u0E19\u0E43\u0E19\u0E0A\u0E48\u0E27\u0E07\u0E1B\u0E35 1920 \u0E2A\u0E33\u0E2B\u0E23\u0E31\u0E1A\u0E1C\u0E39\u0E49\u0E43\u0E0A\u0E49\u0E41\u0E23\u0E07\u0E07\u0E32\u0E19 \u0E19\u0E33\u0E40\u0E19\u0E37\u0E49\u0E2D\u0E2A\u0E31\u0E15\u0E27\u0E4C\u0E41\u0E25\u0E30\u0E1C\u0E31\u0E01\u0E21\u0E32\u0E40\u0E2A\u0E35\u0E22\u0E1A\u0E44\u0E21\u0E49\u0E0A\u0E38\u0E1A\u0E41\u0E1B\u0E49\u0E07\u0E17\u0E2D\u0E14\u0E01\u0E23\u0E2D\u0E1A"
    },
