      "ko": "\uC6B0\uC2A4\uD130\uC18C\uC2A4 4\uD070\uC220, \uB2E4\uC2DC \uC721\uC218 2\uD070\uC220, \uBBF8\uB9BC 1\uD070\uC220, \uC124\uD0D5 1\uC791\uC740\uC220\uC744 \uC0B4\uC9DD \uB053\uC5EC \uC2DD\uD788\uBA74 \uC9DC\uC9C0 \uC54A\uC740 \uC815\uD1B5 \uC18C\uC2A4\uAC00 \uB429\uB2C8\uB2E4.",
      "th": "\u0E2A\u0E39\u0E15\u0E23\u0E0B\u0E2D\u0E2A\u0E04\u0E38\u0E0A\u0E34\u0E04\u0E31\u0E15\u0E2A\u0E36: \u0E0B\u0E2D\u0E2A\u0E27\u0E39\u0E2A\u0E40\u0E15\u0E2D\u0E23\u0E4C 4 \u0E0A\u0E15. + \u0E19\u0E49\u0E33\u0E0B\u0E38\u0E1B\u0E14\u0E32\u0E0A\u0E34 2 \u0E0A\u0E15. + \u0E21\u0E34\u0E23\u0E34\u0E19 1 \u0E0A\u0E15. + \u0E19\u0E49\u0E33\u0E15\u0E32\u0E25 1 \u0E0A\u0E0A. \u0E15\u0E49\u0E21\u0E43\u0E2B\u0E49\u0E40\u0E14\u0E37\u0E2D\u0E14\u0E41\u0E25\u0E49\u0E27\u0E1E\u0E31\u0E01\u0E43\u0E2B\u0E49\u0E40\u0E22\u0E47\u0E19"
