      "ja": "\u5F8C\u918D\u9190\u5929\u7687\u304C\u4E0B\u9D28\u795E\u793E\u306E\u5FA1\u624B\u6D17\u6C60\u3067\u6C34\u3092\u63AC\u3063\u305F\u969B\u3001\u6700\u521D\u306B1\u3064\u306E\u6CE1\u3001\u7D9A\u3044\u30664\u3064\u306E\u6CE1\u304C\u51FA\u305F\u6545\u4E8B\u306B\u7531\u6765\u3002\u4E32\u306B5\u3064\u306E\u56E3\u5B50\u3092\u523A\u3059\u306E\u304C\u672C\u5834\u4EAC\u90FD\u306E\u4F1D\u7D71\u3067\u3059\u3002",
