    "ko": "\uC77C\uC2DD \uC7A5\uC778\uC758 \uAE30\uBCF8\uAE30\uB97C \uC9D1\uC5D0\uC11C \uC644\uBCBD \uC7AC\uD604! 3\uB2E8\uACC4 \uB9D0\uAE30\uC640 \uD0A4\uCE5C\uD0C0\uC6D4 \uC815\uD615 \uAFC0\uD301.",
