        "th": "\u0E15\u0E25\u0E32\u0E14\u0E19\u0E34\u0E0A\u0E34\u0E01\u0E34 \u0E21\u0E34\u0E04\u0E34\u0E40\u0E04\u0E23\u0E31\u0E19 \u0E40\u0E01\u0E35\u0E22\u0E27\u0E42\u0E15"
