    historyStory: {
      "zh-TW": "\u5728\u6C5F\u6236\u58FD\u53F8\u6587\u5316\u4E2D\uFF0C\u300C\u7389\u5B50\uFF08Tamago\uFF09\u300D\u662F\u6AA2\u9A57\u58FD\u53F8\u8077\u4EBA\u529F\u529B\u6700\u91CD\u8981\u7684\u4E00\u9053\u8003\u984C\u3002\u7BC9\u5730\u9B5A\u5E02\u65C1\u56E0\u6E05\u6668\u52DE\u52D5\u8005\u9700\u8981\u8FC5\u901F\u88DC\u5145\u512A\u8CEA\u86CB\u767D\u8CEA\uFF0C\u884D\u751F\u51FA\u73FE\u70E4\u73FE\u5207\u7684\u539A\u5207\u9AD8\u6E6F\u7389\u5B50\u71D2\uFF0C\u71B1\u6C23\u9A30\u9A30\u63D2\u4E0A\u7AF9\u7C64\uFF0C\u6210\u70BA\u4E16\u754C\u5404\u570B\u904A\u5BA2\u9020\u8A2A\u6771\u4EAC\u5FC5\u5403\u7684\u570B\u6C11\u65E9\u9910\uFF01",
      "en": "In sushi tradition, Tamagoyaki tests a chef\u2019s patience and heat control. In Tsukiji, morning fishmongers demanded quick, hearty protein, birthing the famous hot-skewer tamagoyaki stalls.",
      "ja": "\u5BFF\u53F8\u8077\u4EBA\u306E\u8155\u3092\u6E2C\u308B\u30D0\u30ED\u30E1\u30FC\u30BF\u30FC\u3002\u7BC9\u5730\u3067\u306F\u65E9\u671D\u304B\u3089\u50CD\u304F\u4EBA\u3005\u306E\u305F\u3081\u306B\u7518\u53E3\u3084\u51FA\u6C41\u305F\u3063\u3077\u308A\u306E\u713C\u304D\u305F\u3066\u304C\u4E32\u306B\u523A\u3057\u3066\u632F\u308B\u821E\u308F\u308C\u3001\u540D\u7269\u3068\u306A\u308A\u307E\u3057\u305F\u3002",
      "ko": "\uC2A4\uC2DC \uC7A5\uC778\uC758 \uC2E4\uB825\uC744 \uAC00\uB2A0\uD558\uB294 \uAE30\uC900 \uC694\uB9AC\uB85C, \uCE20\uD0A4\uC9C0 \uC5B4\uC2DC\uC7A5\uC5D0\uC11C \uAF2C\uCE58\uC5D0 \uAF42\uC544 \uD314\uAE30 \uC2DC\uC791\uD558\uBA70 \uC138\uACC4\uC801\uC778 \uBA85\uBB3C\uC774 \uB418\uC5C8\uC2B5\uB2C8\uB2E4.",
      "th": "\u0E1A\u0E17\u0E17\u0E14\u0E2A\u0E2D\u0E1A\u0E1D\u0E35\u0E21\u0E37\u0E2D\u0E40\u0E0A\u0E1F\u0E0B\u0E39\u0E0A\u0E34 \u0E43\u0E19\u0E15\u0E25\u0E32\u0E14\u0E0B\u0E36\u0E01\u0E34\u0E08\u0E34\u0E40\u0E23\u0E34\u0E48\u0E21\u0E02\u0E32\u0E22\u0E41\u0E1A\u0E1A\u0E40\u0E2A\u0E35\u0E22\u0E1A\u0E44\u0E21\u0E49\u0E23\u0E49\u0E2D\u0E19\u0E46 \u0E43\u0E2B\u0E49\u0E04\u0E19\u0E07\u0E32\u0E19\u0E17\u0E32\u0E19\u0E15\u0E2D\u0E19\u0E40\u0E0A\u0E49\u0E32\u0E08\u0E19\u0E42\u0E14\u0E48\u0E07\u0E14\u0E31\u0E07"
    },
