    "ko": "\uCE7C\uC9D1\uC744 \uB123\uC740 \uB450\uD23C\uD55C \uD1B5\uC624\uC9D5\uC5B4\uC5D0 \uB2E8\uC9E0 \uAC04\uC7A5 \uBC84\uD130 \uC18C\uC2A4\uB97C \uB367\uBC1C\uB77C \uAD6C\uC6CC\uB0B8 \uCD5C\uACE0\uC758 \uC220\uC548\uC8FC",
