  troubleshooting: [
    {
      id: "trouble-ika-1",
      problem: {
        "zh-TW": "\u9B77\u9B5A\u70E4\u51FA\u4F86\u53E3\u611F\u50CF\u6A61\u76AE\u7B4B\u4E00\u6A23\u6B7B\u786C\u4E7E\u97CC\uFF1F",
        "en": "Why did the squid turn out tough and rubbery like shoe leather?",
        "ja": "\u30A4\u30AB\u304C\u786C\u304F\u306A\u3063\u3066\u3057\u307E\u3044\u3001\u30B4\u30E0\u306E\u3088\u3046\u306A\u98DF\u611F\u306B\u306A\u3063\u3066\u3057\u307E\u3044\u307E\u3057\u305F\u3002",
        "ko": "\uC624\uC9D5\uC5B4\uAC00 \uACE0\uBB34\uCC98\uB7FC \uC9C8\uACA8\uC84C\uC5B4\uC694.",
        "th": "\u0E17\u0E33\u0E44\u0E21\u0E1B\u0E25\u0E32\u0E2B\u0E21\u0E36\u0E01\u0E40\u0E2B\u0E19\u0E35\u0E22\u0E27\u0E41\u0E02\u0E47\u0E07\u0E40\u0E2B\u0E21\u0E37\u0E2D\u0E19\u0E22\u0E32\u0E07\u0E25\u0E1A?"
      },
      cause: {
        "zh-TW": "\u714E\u70E4\u6642\u9593\u904E\u9577\uFF08\u8D85\u904E 5 \u5206\u9418\uFF09\uFF0C\u9B77\u9B5A\u86CB\u767D\u8CEA\u8B8A\u6027\u812B\u6C34\u3002",
        "en": "Overcooked! Squid must be flash-cooked in under 4 minutes total; long heat denatures proteins into tough fibers.",
        "ja": "\u52A0\u71B1\u6642\u9593\u304C\u9577\u3059\u304E\u305F\u3053\u3068\u304C\u539F\u56E0\u3067\u3059\u3002\u30A4\u30AB\u306F\u6570\u5206\u3067\u706B\u304C\u901A\u308B\u305F\u3081\u30B9\u30D4\u30FC\u30C9\u52DD\u8CA0\u3067\u3059\u3002",
        "ko": "\uB108\uBB34 \uC624\uB798 \uAD6C\uC6E0\uAE30 \uB54C\uBB38\uC785\uB2C8\uB2E4. \uC624\uC9D5\uC5B4\uB294 3~4\uBD84 \uC774\uB0B4\uB85C \uBE60\uB974\uAC8C \uC870\uB9AC\uD574\uC57C \uBD80\uB4DC\uB7FD\uC2B5\uB2C8\uB2E4.",
        "th": "\u0E22\u0E48\u0E32\u0E07\u0E19\u0E32\u0E19\u0E40\u0E01\u0E34\u0E19\u0E44\u0E1B \u0E1B\u0E25\u0E32\u0E2B\u0E21\u0E36\u0E01\u0E2A\u0E38\u0E01\u0E07\u0E48\u0E32\u0E22\u0E21\u0E32\u0E01 \u0E2B\u0E32\u0E01\u0E40\u0E01\u0E34\u0E19 4-5 \u0E19\u0E32\u0E17\u0E35\u0E40\u0E19\u0E37\u0E49\u0E2D\u0E08\u0E30\u0E2B\u0E14\u0E15\u0E31\u0E27\u0E41\u0E25\u0E30\u0E40\u0E2B\u0E19\u0E35\u0E22\u0E27"
      },
      solution: {
        "zh-TW": "\u5148\u4E7E\u714E\u81F3\u8F49\u767D\u5373\u53EF\uFF08\u5169\u9762\u5404\u7D04 1.5 \u5206\u9418\uFF09\uFF0C\u4E0B\u91AC\u6C41\u5F8C\u5927\u706B\u8FC5\u901F\u6536\u6C41 1 \u5206\u9418\u7ACB\u523B\u8D77\u934B\uFF0C\u4FDD\u6301\u9BAE\u5AE9\u591A\u6C41\uFF01",
        "en": "Sear plain for only 1.5 mins per side, glaze sauce for 1 min, and remove from heat immediately.",
        "ja": "\u4E21\u9762\u30B5\u30C3\u3068\u713C\u304D\u3001\u30BF\u30EC\u3092\u5165\u308C\u305F\u3089\u5F37\u706B\u3067\u77ED\u6642\u9593\u3067\u7D61\u3081\u3066\u3059\u3050\u306B\u706B\u3092\u6B62\u3081\u307E\u3057\u3087\u3046\u3002",
        "ko": "\uC55E\uB4A4\uB85C 1.5\uBD84\uC529\uB9CC \uAD7D\uACE0 \uC591\uB150\uC744 \uB123\uC740 \uB4A4 \uC13C \uBD88\uC5D0\uC11C 1\uBD84 \uB9CC\uC5D0 \uBE60\uB974\uAC8C \uC878\uC5EC \uBD88\uC744 \uB044\uC138\uC694.",
        "th": "\u0E22\u0E48\u0E32\u0E07\u0E14\u0E49\u0E32\u0E19\u0E25\u0E30 1.5 \u0E19\u0E32\u0E17\u0E35\u0E1E\u0E2D \u0E40\u0E21\u0E37\u0E48\u0E2D\u0E43\u0E2A\u0E48\u0E0B\u0E2D\u0E2A\u0E43\u0E2B\u0E49\u0E40\u0E04\u0E35\u0E48\u0E22\u0E27\u0E44\u0E1F\u0E41\u0E23\u0E07 1 \u0E19\u0E32\u0E17\u0E35\u0E41\u0E25\u0E49\u0E27\u0E1B\u0E34\u0E14\u0E44\u0E1F\u0E17\u0E31\u0E19\u0E17\u0E35"
      }
    }
  ],
  proTips: [
    {
      "zh-TW": "\u3010\u52A0\u4E00\u5C0F\u584A\u9EC3\u6CB9\u7684\u5317\u6D77\u9053\u9B54\u6CD5\u3011\uFF1A\u5728\u6700\u5F8C\u6536\u6C41\u6642\u6295\u5165 10g \u5976\u6CB9\uFF0C\u80FD\u8B93\u65E5\u5F0F\u91AC\u6CB9\u7684\u9AD8\u6EAB\u7126\u9999\u8F49\u5316\u70BA\u6FC3\u90C1\u5976\u9999\u7684\u300C\u7126\u304C\u3057\u30D0\u30BF\u30FC\u91A4\u6CB9\uFF08\u7126\u9999\u5976\u6CB9\u91AC\u6CB9\uFF09\u300D\uFF0C\u98A8\u5473\u77AC\u9593\u5347\u7D1A\u9802\u7D1A\u6D77\u9BAE\u5C45\u9152\u5C4B\u6C34\u6E96\uFF01",
      "en": 'Adding a knob of butter at the end creates Japanese "Kogashi Butter Shoyu" (brown butter soy sauce), a legendary pairing for grilled seafood.',
      "ja": "\u3010\u7126\u304C\u3057\u30D0\u30BF\u30FC\u91A4\u6CB9\u306E\u9B54\u6CD5\u3011\uFF1A\u4ED5\u4E0A\u3052\u306E\u30D0\u30BF\u30FC\u304C\u91A4\u6CB9\u306E\u5869\u89D2\u3092\u53D6\u308A\u3001\u30B3\u30AF\u3068\u9999\u3070\u3057\u3055\u3092\u5287\u7684\u306B\u683C\u4E0A\u3052\u3057\u307E\u3059\u3002",
      "ko": "\uB9C8\uC9C0\uB9C9\uC5D0 \uB123\uB294 \uBC84\uD130 \uD55C \uC870\uAC01\uC774 \uAC04\uC7A5\uACFC \uC5B4\uC6B0\uB7EC\uC838 \uD658\uC0C1\uC801\uC778 \u2018\uBC84\uD130 \uAC04\uC7A5 \uBD88\uB9DB\u2019\uC744 \uB9CC\uB4E4\uC5B4\uB0C5\uB2C8\uB2E4.",
      "th": '\u0E43\u0E2A\u0E48\u0E40\u0E19\u0E22\u0E25\u0E07\u0E44\u0E1B\u0E15\u0E2D\u0E19\u0E17\u0E49\u0E32\u0E22\u0E08\u0E30\u0E40\u0E01\u0E34\u0E14\u0E40\u0E1B\u0E47\u0E19\u0E0B\u0E2D\u0E2A "\u0E40\u0E19\u0E22\u0E42\u0E0A\u0E22\u0E38\u0E44\u0E2B\u0E21\u0E49" \u0E2A\u0E39\u0E15\u0E23\u0E25\u0E31\u0E1A\u0E02\u0E2D\u0E07\u0E2E\u0E2D\u0E01\u0E44\u0E01\u0E42\u0E14\u0E17\u0E35\u0E48\u0E2B\u0E2D\u0E21\u0E25\u0E49\u0E33\u0E25\u0E36\u0E01'
    }
  ]
