      "zh-TW": "\u53EF\u6A02\u9905\u6E90\u81EA\u6CD5\u570B\u7684\u70B8\u8089\u4E38\uFF08Croquette\uFF09\uFF0C\u660E\u6CBB\u6642\u4EE3\u50B3\u5165\u65E5\u672C\u5F8C\uFF0C\u7531\u65BC\u7576\u6642\u4E73\u88FD\u54C1\u9AD8\u6602\uFF0C\u5EB6\u6C11\u5C07\u6602\u8CB4\u7684\u767D\u91AC\u6539\u70BA\u9B06\u8EDF\u7DBF\u5BC6\u7684\u84B8\u99AC\u9234\u85AF\uFF0C\u6DF7\u5165\u6D0B\u8525\u788E\u8207\u7092\u725B\u7D5E\u8089\u3002\u5927\u6B63\u5E74\u9593\u8207\u5496\u54E9\u98EF\u3001\u70B8\u8C6C\u6392\u4E26\u5217\u70BA\u300C\u5927\u6B63\u4E09\u5927\u6D0B\u98DF\u300D\uFF0C\u6210\u70BA\u65E5\u672C\u5BB6\u5EAD\u8207\u8857\u982D\u8089\u8216\u6700\u89AA\u5207\u7684\u570B\u6C11\u5C0F\u5403\uFF01",
      "en": 'Adapted from French croquettes during the Meiji era by substituting expensive b\xE9chamel with fluffy steamed potatoes and seasoned ground beef. Crowned one of the "Big Three Y\u014Dshoku Dishes".',
      "ja": "\u30D5\u30E9\u30F3\u30B9\u6599\u7406\u306E\u30AF\u30ED\u30B1\u30C3\u30C8\u304C\u660E\u6CBB\u671F\u306B\u65E5\u672C\u98A8\u306B\u30A2\u30EC\u30F3\u30B8\u3055\u308C\u3001\u5B89\u4FA1\u3067\u6804\u990A\u6E80\u70B9\u306A\u30B8\u30E3\u30AC\u30A4\u30E2\u3068\u725B\u8089\u3092\u5408\u308F\u305B\u308B\u30B9\u30BF\u30A4\u30EB\u306B\u3002\u5927\u6B63\u4E09\u5927\u6D0B\u98DF\u306E\u4E00\u3064\u3068\u3057\u3066\u89AA\u3057\u307E\u308C\u307E\u3057\u305F\u3002",
      "ko": "\uD504\uB791\uC2A4 \uD06C\uB85C\uCF13\uC744 \uC77C\uBCF8\uC2DD\uC73C\uB85C \uAC1C\uB7C9\uD558\uC5EC \uAC10\uC790\uC640 \uB2E4\uC9C4 \uACE0\uAE30\uB97C \uB123\uC5B4 \uB9CC\uB4E0 \uB2E4\uC774\uC1FC \uC2DC\uB300 3\uB300 \uC591\uC2DD \uC911 \uD558\uB098\uC785\uB2C8\uB2E4.",
      "th": "\u0E14\u0E31\u0E14\u0E41\u0E1B\u0E25\u0E07\u0E21\u0E32\u0E08\u0E32\u0E01\u0E42\u0E04\u0E23\u0E40\u0E01\u0E15\u0E4C\u0E1D\u0E23\u0E31\u0E48\u0E07\u0E40\u0E28\u0E2A\u0E43\u0E19\u0E22\u0E38\u0E04\u0E40\u0E21\u0E08\u0E34 \u0E42\u0E14\u0E22\u0E43\u0E0A\u0E49\u0E21\u0E31\u0E19\u0E1D\u0E23\u0E31\u0E48\u0E07\u0E1A\u0E14\u0E41\u0E17\u0E19\u0E44\u0E27\u0E17\u0E4C\u0E0B\u0E2D\u0E2A\u0E08\u0E19\u0E01\u0E25\u0E32\u0E22\u0E40\u0E1B\u0E47\u0E19\u0E2D\u0E32\u0E2B\u0E32\u0E23\u0E22\u0E2D\u0E14\u0E19\u0E34\u0E22\u0E21"
