      "zh-TW": "\u76F8\u50B3\u5E73\u5B89\u6642\u4EE3\u672B\u671F\u540D\u5C07\u6B66\u85CF\u574A\u5F01\u6176\u5728\u53D7\u50B7\u990A\u50B7\u6642\uFF0C\u5C07\u9EB5\u7CCA\u5012\u5728\u96A8\u8EAB\u9285\u947C\uFF08Dora\uFF09\u4E0A\u714E\u6210\u5713\u9905\uFF0C\u5305\u88F9\u7D05\u8C46\u9921\u611F\u8B1D\u6536\u7559\u4ED6\u7684\u8FB2\u5BB6\uFF0C\u6545\u540D\u300C\u9285\u947C\u71D2\u300D\u3002\u5927\u6B63\u4E09\u5E74\uFF081914\u5E74\uFF09\u4E0A\u91CE\u540D\u5E97\u300C\u5154\u5C4B\u300D\u6539\u70BA\u73FE\u4EE3\u7684\u300C\u96D9\u7247\u593E\u9921\u300D\u5F62\u5F0F\uFF0C\u5F9E\u6B64\u6210\u70BA\u5168\u65E5\u672C\u6700\u5177\u4EE3\u8868\u6027\u7684\u548C\u83D3\u5B50\uFF01",
