    "ko": "\uC0DD\uBE75\uAC00\uB8E8\uC758 \uB208\uAF43 \uBC14\uC0AD\uD568! \uC800\uC628 \uC219\uC131\uACFC \uACE0\uC628 2\uCC28 \uD280\uAE40\uC73C\uB85C \uCD09\uCD09\uD55C \uC721\uC999\uC758 \uC808\uC815",
    "th": "\u0E40\u0E01\u0E25\u0E47\u0E14\u0E02\u0E19\u0E21\u0E1B\u0E31\u0E07\u0E2A\u0E14\u0E01\u0E23\u0E2D\u0E1A\u0E1F\u0E39\u0E1F\u0E48\u0E2D\u0E07 \u0E40\u0E19\u0E37\u0E49\u0E2D\u0E2B\u0E21\u0E39\u0E2A\u0E31\u0E19\u0E19\u0E2D\u0E01\u0E0A\u0E34\u0E49\u0E19\u0E2B\u0E19\u0E32\u0E19\u0E38\u0E48\u0E21\u0E0A\u0E38\u0E48\u0E21\u0E09\u0E48\u0E33 \u0E17\u0E2D\u0E14\u0E2A\u0E2D\u0E07\u0E2D\u0E38\u0E13\u0E2B\u0E20\u0E39\u0E21\u0E34"
