    historyStory: {
      "zh-TW": "\u660E\u6CBB 32 \u5E74\uFF081899 \u5E74\uFF09\uFF0C\u9280\u5EA7\u897F\u9910\u5EF3\u300C\u7149\u74E6\u4EAD\u300D\u5C07\u6B50\u6D32\u714E\u725B\u6392\uFF08C\xF4telette\uFF09\u6539\u4EE5\u6DF1\u6CB9\u539A\u70B8\u8C6C\u6392\u9AA8\u8089\uFF0C\u4E26\u9996\u5275\u642D\u914D\u6E05\u723D\u89E3\u6CB9\u81A9\u7684\u5207\u7D30\u9AD8\u9E97\u83DC\u7D72\u8207\u7C73\u98EF\uFF0C\u958B\u5275\u4E86\u73FE\u4EE3\u65E5\u5F0F\u70B8\u8C6C\u6392\u3002\u5927\u6B63\u5E74\u9593\u4E0A\u91CE\u300C\u307D\u3093\u591A\u672C\u5BB6\u300D\u53BB\u9AA8\u6539\u7528\u539A\u5207\u91CC\u808C\uFF0C\u6B63\u5F0F\u5960\u5B9A\u4E86\u4E16\u754C\u805E\u540D\u7684\u9EC3\u91D1\u539A\u5207\u70B8\u8C6C\u6392\u5730\u4F4D\uFF01",
      "en": 'Invented in 1899 at Rengatei in Ginza as "Pork Cutlet", pioneering the iconic shredded cabbage side. Later refined in Ueno into the boneless thick-cut masterpiece we relish today.',
      "ja": "\u660E\u6CBB32\u5E74\u3001\u9280\u5EA7\u300C\u7149\u74E6\u4EAD\u300D\u304C\u30AB\u30C4\u30EC\u30C4\u3092\u65E5\u672C\u4EBA\u5411\u3051\u306B\u5929\u3077\u3089\u306E\u3088\u3046\u306B\u6DF1\u934B\u3067\u63DA\u3052\u3001\u5343\u5207\u308A\u30AD\u30E3\u30D9\u30C4\u3092\u6DFB\u3048\u305F\u306E\u304C\u59CB\u307E\u308A\u3002\u5F8C\u306B\u4E0A\u91CE\u3067\u539A\u5207\u308A\u30ED\u30FC\u30B9\u306E\u30B9\u30BF\u30A4\u30EB\u304C\u78BA\u7ACB\u3055\u308C\u307E\u3057\u305F\u3002",
      "ko": "1899\uB144 \uAE34\uC790 \uB80C\uAC00\uD14C\uC774\uC5D0\uC11C \uC2DC\uC791\uB418\uC5B4 \uC6B0\uC5D0\uB178\uC5D0\uC11C \uB450\uD23C\uD55C \uB4F1\uC2EC\uC744 \uD280\uACA8\uB0B4\uB294 \uD615\uD0DC\uB85C \uC644\uC131\uB41C \uB300\uD45C\uC801\uC778 \uC77C\uC2DD \uC694\uB9AC\uC785\uB2C8\uB2E4.",
      "th": "\u0E01\u0E33\u0E40\u0E19\u0E34\u0E14\u0E02\u0E36\u0E49\u0E19\u0E43\u0E19\u0E1B\u0E35 1899 \u0E17\u0E35\u0E48\u0E01\u0E34\u0E19\u0E0B\u0E48\u0E32 \u0E42\u0E14\u0E22\u0E14\u0E31\u0E14\u0E41\u0E1B\u0E25\u0E07\u0E04\u0E31\u0E15\u0E40\u0E25\u0E47\u0E15\u0E22\u0E38\u0E42\u0E23\u0E1B\u0E43\u0E2B\u0E49\u0E17\u0E2D\u0E14\u0E43\u0E19\u0E19\u0E49\u0E33\u0E21\u0E31\u0E19\u0E17\u0E48\u0E27\u0E21 \u0E40\u0E2A\u0E34\u0E23\u0E4C\u0E1F\u0E04\u0E39\u0E48\u0E01\u0E30\u0E2B\u0E25\u0E48\u0E33\u0E1B\u0E25\u0E35\u0E0B\u0E2D\u0E22"
    },
