      "zh-TW": "\u725B\u4E3C\u524D\u8EAB\u6E90\u81EA\u660E\u6CBB\u7DAD\u65B0\u6642\u671F\u7684\u300C\u725B\u934B\uFF08Gy\u016Bnabe\uFF09\u300D\uFF0C\u5EB6\u6C11\u5C07\u6602\u8CB4\u7684\u725B\u8089\u788E\u8207\u9B54\u828B\u3001\u6D0B\u8525\u6F86\u5728\u98EF\u4E0A\u98DF\u7528\u3002\u660E\u6CBB 32 \u5E74\uFF081899 \u5E74\uFF09\uFF0C\u677E\u7530\u69AE\u5409\u5728\u6771\u4EAC\u65E5\u672C\u6A4B\u9B5A\u5E02\u5834\u5275\u8FA6\u300C\u5409\u91CE\u5BB6\u300D\uFF0C\u767C\u660E\u4E86\u300C\u5FEB\u901F\u3001\u5E73\u50F9\u3001\u7F8E\u5473\uFF08\u3046\u307E\u3044\u3001\u3084\u3059\u3044\u3001\u306F\u3084\u3044\uFF09\u300D\u7684\u725B\u4E3C\uFF0C\u6210\u70BA\u73FE\u4EE3\u65E5\u672C\u4E0A\u73ED\u65CF\u6700\u4F9D\u8CF4\u7684\u80FD\u91CF\u6E90\u6CC9\uFF01",
      "en": "Born during the Meiji Restoration as an offshoot of beef hotpot (Gyunabe). In 1899, Eikichi Matsuda founded Yoshinoya in Nihonbashi, revolutionizing fast, affordable, hearty comfort food.",
