    "ko": "\uC774\uC790\uCE74\uC57C \uB9C8\uBB34\uB9AC\uC758 \uC815\uC11D! \uD504\uB77C\uC774\uD32C\uC774\uB098 \uC5D0\uC5B4\uD504\uB77C\uC774\uC5B4\uB85C \uBC14\uC0AD\uD55C \uB204\uB8FD\uC9C0 \uC8FC\uBA39\uBC25 \uC644\uC131.",
