      "ko": "\uAC00\uB098\uAC00\uC640\uD604 \uC694\uCF54\uC2A4\uCE74\uC2DC (\uD574\uAD70 \uCE74\uB808\uC758 \uBC1C\uC0C1\uC9C0)",
