    historyStory: {
      "zh-TW": "\u660E\u6CBB\u6642\u671F\u65E5\u672C\u5E1D\u570B\u6D77\u8ECD\u501F\u9452\u82F1\u570B\u7687\u5BB6\u6D77\u8ECD\u7684\u725B\u8089\u6FC3\u6E6F\uFF0C\u7D50\u5408\u5370\u5EA6\u9999\u6599\u8207\u5C0F\u9EA5\u7C89\u7092\u88FD\u6210\u6FC3\u7A20\u6FC3\u90C1\u7684\u65E5\u5F0F\u5496\u54E9\uFF0C\u6F86\u5728\u767D\u7C73\u98EF\u4E0A\u9632\u6B62\u58EB\u5175\u56E0\u6688\u8239\u7051\u7FFB\uFF0C\u4E26\u56FA\u5B9A\u6BCF\u9031\u4E94\u4F9B\u61C9\uFF08\u9632\u6B62\u6D77\u8ECD\u5728\u832B\u832B\u5927\u6D77\u4E2D\u55AA\u5931\u661F\u671F\u89C0\u5FF5\uFF09\u3002\u662D\u548C\u6642\u4EE3\u666E\u53CA\u81F3\u65E5\u672C\u5BB6\u5BB6\u6236\u6236\uFF0C\u6F14\u8B8A\u70BA\u878D\u5408\u860B\u679C\u6CE5\u3001\u8702\u871C\u8207\u9AD8\u6E6F\u7684\u65E5\u5F0F\u7368\u5275\u6ECB\u5473\uFF01",
      "en": "Introduced to Japan via the Royal Navy in the Meiji era, thickened with a flour roux so it wouldn\u2019t spill on rolling seas. Fixed as the Friday naval meal, it evolved into Japan\u2019s #1 home comfort food.",
      "ja": "\u660E\u6CBB\u6642\u4EE3\u3001\u65E5\u672C\u6D77\u8ECD\u304C\u30A4\u30AE\u30EA\u30B9\u6D77\u8ECD\u306E\u30AB\u30EC\u30FC\u30B7\u30C1\u30E5\u30FC\u3092\u6539\u826F\u3057\u3001\u63FA\u308C\u308B\u8239\u4E0A\u3067\u3082\u3053\u307C\u308C\u306A\u3044\u3088\u3046\u5C0F\u9EA6\u7C89\u3067\u3068\u308D\u307F\u3092\u3064\u3051\u305F\u306E\u304C\u767A\u7965\u3002\u91D1\u66DC\u65E5\u306B\u98DF\u3079\u308B\u7FD2\u6163\u306F\u4ECA\u3082\u6D77\u4E0A\u81EA\u885B\u968A\u306B\u7D9A\u3044\u3066\u3044\u307E\u3059\u3002",
      "ko": "\uBA54\uC774\uC9C0 \uC2DC\uB300 \uD574\uAD70\uC5D0\uC11C \uD754\uB4E4\uB9AC\uB294 \uBC30 \uC704\uC5D0\uC11C \uC3DF\uC544\uC9C0\uC9C0 \uC54A\uB3C4\uB85D \uAC78\uCB49\uD558\uAC8C \uB9CC\uB4E4\uC5B4 \uBC25\uACFC \uD568\uAED8 \uBA39\uB358 \uAC83\uC5D0\uC11C \uC720\uB798\uD588\uC2B5\uB2C8\uB2E4.",
      "th": "\u0E01\u0E2D\u0E07\u0E17\u0E31\u0E1E\u0E40\u0E23\u0E37\u0E2D\u0E0D\u0E35\u0E48\u0E1B\u0E38\u0E48\u0E19\u0E19\u0E33\u0E2A\u0E39\u0E15\u0E23\u0E21\u0E32\u0E08\u0E32\u0E01\u0E23\u0E32\u0E0A\u0E19\u0E32\u0E27\u0E35\u0E2D\u0E31\u0E07\u0E01\u0E24\u0E29 \u0E1B\u0E23\u0E31\u0E1A\u0E43\u0E2B\u0E49\u0E02\u0E49\u0E19\u0E40\u0E1E\u0E37\u0E48\u0E2D\u0E44\u0E21\u0E48\u0E43\u0E2B\u0E49\u0E2B\u0E01\u0E40\u0E27\u0E25\u0E32\u0E01\u0E25\u0E32\u0E07\u0E17\u0E30\u0E40\u0E25"
    },
