    historyStory: {
      "zh-TW": "Tsukune \u6E90\u81EA\u65E5\u8A9E\u300C\u3064\u304F\u306D\u308B (\u634F\u3001\u63C9\u6210\u5718)\u300D\u3002\u5C07\u96DE\u8089\u7D5E\u8089\u63C9\u5165\u8591\u6C41\u3001\u8525\u82B1\u8207\u5207\u788E\u7684\u96DE\u8EDF\u9AA8\uFF0C\u7528\u7AF9\u7C64\u4E32\u8D77\u70AD\u706B\u7FFB\u70E4\u3002\u5176\u9748\u9B42\u5728\u65BC\u6D78\u6F64\u4E86\u6578\u5341\u5E74\u8001\u6EF7\u6C41\u7684\u751C\u9E79\u300CTare\u300D\u91AC\uFF0C\u6700\u5F8C\u4E00\u5B9A\u8981\u914D\u4E0A\u4E00\u9846\u91D1\u9EC3\u751F\u98DF\u7D1A\u86CB\u9EC3\uFF0C\u8102\u9999\u8207\u86CB\u9999\u5728\u820C\u5C16\u878D\u5316\u3002",
      "en": 'Derived from the Japanese verb "tsukuneru" meaning to knead by hand. Minced chicken is combined with grated ginger, scallions, and finely chopped cartilage for crunch, then grilled over charcoal. The hallmark is basting with rich sweet tare sauce and dipping into fresh pasteurized egg yolk.',
      "ja": "\u300C\u624B\u3067\u3053\u306D\u3066\u4E38\u3081\u308B\u300D\u3053\u3068\u304B\u3089\u305D\u306E\u540D\u304C\u3064\u3044\u305F\u3064\u304F\u306D\u3002\u8EDF\u9AA8\u306E\u98DF\u611F\u3068\u30CD\u30AE\u30FB\u751F\u59DC\u306E\u98A8\u5473\u3092\u52B9\u304B\u305B\u305F\u8089\u3060\u306D\u3092\u3001\u4EE3\u3005\u53D7\u3051\u7D99\u304C\u308C\u305F\u79D8\u4F1D\u30BF\u30EC\u306B\u6F5C\u3089\u305B\u3066\u713C\u304D\u4E0A\u3052\u307E\u3059\u3002\u6FC3\u539A\u306A\u5375\u9EC4\u3092\u305F\u3063\u3077\u308A\u7D61\u3081\u3066\u98DF\u3079\u308B\u306E\u304C\u6700\u9AD8\u306E\u8D05\u6CA2\u3067\u3059\u3002",
      "ko": "\uC190\uC73C\uB85C \uBE5A\uC5B4 \uB465\uAE00\uAC8C \uB9CC\uB4E0\uB2E4\uB294 \uC758\uBBF8\uC758 \uCE20\uCFE0\uB124. \uB2ED\uC5F0\uACE8\uC744 \uB2E4\uC838 \uB123\uC5B4 \uC539\uB294 \uB9DB\uC744 \uC0B4\uB9AC\uACE0 \uD2B9\uC81C \uD0C0\uB808 \uC18C\uC2A4\uB97C \uB367\uBC1C\uB77C \uAD6C\uC6CC\uB0C5\uB2C8\uB2E4. \uC2E0\uC120\uD55C \uACC4\uB780 \uB178\uB978\uC790\uC5D0 \uD479 \uCC0D\uC5B4 \uBA39\uC73C\uBA74 \uACE0\uC18C\uD568\uC774 \uBC30\uAC00\uB429\uB2C8\uB2E4.",
      "th": "\u0E0B\u0E36\u0E04\u0E38\u0E40\u0E19\u0E30 \u0E21\u0E35\u0E04\u0E27\u0E32\u0E21\u0E2B\u0E21\u0E32\u0E22\u0E27\u0E48\u0E32\u0E01\u0E32\u0E23\u0E1B\u0E31\u0E49\u0E19\u0E14\u0E49\u0E27\u0E22\u0E21\u0E37\u0E2D \u0E40\u0E1B\u0E47\u0E19\u0E44\u0E01\u0E48\u0E1A\u0E14\u0E1C\u0E2A\u0E21\u0E02\u0E34\u0E07 \u0E15\u0E49\u0E19\u0E2B\u0E2D\u0E21 \u0E41\u0E25\u0E30\u0E01\u0E23\u0E30\u0E14\u0E39\u0E01\u0E2D\u0E48\u0E2D\u0E19\u0E44\u0E01\u0E48\u0E01\u0E23\u0E38\u0E1A\u0E01\u0E23\u0E2D\u0E1A \u0E40\u0E2A\u0E35\u0E22\u0E1A\u0E44\u0E21\u0E49\u0E22\u0E48\u0E32\u0E07\u0E1A\u0E19\u0E40\u0E15\u0E32\u0E16\u0E48\u0E32\u0E19 \u0E17\u0E32\u0E0B\u0E2D\u0E2A\u0E17\u0E32\u0E40\u0E23\u0E30\u0E23\u0E2A\u0E40\u0E02\u0E49\u0E21\u0E02\u0E49\u0E19 \u0E41\u0E25\u0E30\u0E08\u0E34\u0E49\u0E21\u0E44\u0E02\u0E48\u0E41\u0E14\u0E07\u0E2A\u0E14\u0E40\u0E1E\u0E37\u0E48\u0E2D\u0E04\u0E27\u0E32\u0E21\u0E19\u0E38\u0E48\u0E21\u0E25\u0E30\u0E21\u0E38\u0E19"
    },
