          "ja": "\u8EDF\u9AA8\u304C\u624B\u306B\u5165\u3089\u306A\u3044\u5834\u5408\u306F\u3001\u30A8\u30EA\u30F3\u30AE\u3084\u30EC\u30F3\u30B3\u30F3\u3092\u7D30\u304B\u304F\u523B\u3093\u3067\u5165\u308C\u308B\u3068\u826F\u3044\u98DF\u611F\u306B\u306A\u308A\u307E\u3059\u3002",
          "ko": "\uB2ED\uC5F0\uACE8\uC774 \uC5C6\uC73C\uBA74 \uC798\uAC8C \uC36C \uC5F0\uADFC\uC774\uB098 \uC0C8\uC1A1\uC774\uBC84\uC12F\uC73C\uB85C \uC544\uC0AD\uD55C \uC2DD\uAC10\uC744 \uB0BC \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
          "th": "\u0E2B\u0E32\u0E01\u0E44\u0E21\u0E48\u0E21\u0E35\u0E01\u0E23\u0E30\u0E14\u0E39\u0E01\u0E2D\u0E48\u0E2D\u0E19\u0E44\u0E01\u0E48 \u0E2A\u0E32\u0E21\u0E32\u0E23\u0E16\u0E43\u0E0A\u0E49\u0E41\u0E2B\u0E49\u0E27\u0E2B\u0E23\u0E37\u0E2D\u0E40\u0E2B\u0E47\u0E14\u0E2D\u0E2D\u0E23\u0E34\u0E19\u0E08\u0E34\u0E2A\u0E31\u0E1A\u0E25\u0E30\u0E40\u0E2D\u0E35\u0E22\u0E14\u0E41\u0E17\u0E19\u0E44\u0E14\u0E49"
